<template><section><div class="page-header"><div><div class="eyebrow">{{ t('nav.master') }}</div><h1>{{ t('overview.title') }}</h1><p>{{ t('overview.description') }}</p></div><button class="button secondary" type="button" :disabled="busy" @click="load"><Icon name="refresh" size="sm" />{{ t('common.refresh') }}</button></div><div class="stats-grid"><StatCard :label="t('overview.clients')" :value="data.clients" icon="users" /><StatCard :label="t('overview.servers')" :value="data.servers" icon="server" /><StatCard :label="t('overview.tunnels')" :value="data.tunnels" icon="arrowsUpDown" /></div><div class="panel next-panel"><div class="panel-heading"><div><h2>{{ t('overview.next') }}</h2><p>{{ t('overview.nextHint') }}</p></div><Icon name="arrowRight" size="lg" /></div><div class="flow"><RouterLink to="/servers">1&nbsp; {{ t('nav.servers') }}</RouterLink><span>→</span><RouterLink to="/clients">2&nbsp; {{ t('nav.clients') }}</RouterLink><span>→</span><RouterLink to="/tunnels">3&nbsp; {{ t('nav.tunnels') }}</RouterLink></div></div></section></template>
<script setup lang="ts">import { onMounted,reactive,ref } from 'vue'; import { useI18n } from 'vue-i18n'; import Icon from '../components/icons/Icon.vue'; import { StatCard } from '../components/common'; import { api } from '../api'; import { useToastStore } from '../stores/toast'; const {t}=useI18n(); const toast=useToastStore(); const data=reactive({clients:0,servers:0,tunnels:0});const busy=ref(false);const load=async()=>{busy.value=true;try{Object.assign(data,await api.overview())}catch{toast.show(t('common.error'),'error')}finally{busy.value=false}};onMounted(load)</script>
